const ChargeObjectSchema = z
  .object({
    lago_id: z
      .uuid()
      .openapi({
        description: 'Unique identifier of charge, created by Lago.',
        example: '1a901a90-1a90-1a90-1a90-1a901a901a90',
      }),
    lago_billable_metric_id: z
      .uuid()
      .openapi({
        description: 'Unique identifier of the billable metric created by Lago.',
        example: '1a901a90-1a90-1a90-1a90-1a901a901a90',
      }),
    code: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Unique code identifying the charge within the plan.',
        example: 'api_requests_charge',
      }),
    billable_metric_code: z
      .string()
      .openapi({ description: 'Unique code identifying a billable metric.', example: 'requests' }),
    invoice_display_name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Specifies the name that will be displayed on an invoice. If no value is set for this field, the name of the actual charge will be used as the default display name.',
        example: 'Setup',
      }),
    created_at: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          'The date and time when the charge was created. It is expressed in UTC format according to the ISO 8601 datetime standard.',
        example: '2022-09-14T16:35:31Z',
      }),
    charge_model: ChargeModelEnumSchema,
    pay_in_advance: z
      .boolean()
      .openapi({
        description:
          'This field determines the billing timing for this specific usage-based charge. When set to `true`, the charge is due and invoiced immediately. Conversely, when set to `false`, the charge is due and invoiced at the end of each billing period.',
        example: true,
      }),
    invoiceable: z
      .boolean()
      .openapi({
        description:
          'This field specifies whether the charge should be included in a proper invoice. If set to `false`, no invoice will be issued for this charge. You can only set it to `false` when `pay_in_advance` is `true`.',
        example: true,
      }),
    regroup_paid_fees: z
      .union([z.literal(null), z.literal('invoice')])
      .nullable()
      .openapi({
        description:
          'This setting can only be configured if `pay_in_advance` is `true` and `invoiceable` is `false`.\nThis field determines whether and when the charge fee should be included in\nthe invoice. If `null`, no invoice will be issued for this charge fee.\nIf `invoice`, an invoice will be generated at the end of the period,\nconsolidating all charge fees with a succeeded payment status.',
        example: 'invoice',
      }),
    prorated: z
      .boolean()
      .openapi({
        example: false,
        description:
          'Specifies whether a charge is prorated based on the remaining number of days in the billing period or billed fully.\n\n- If set to `true`, the charge is prorated based on the remaining days in the current billing period.\n- If set to `false`, the charge is billed in full.\n- If not defined in the request, default value is `false`.',
      }),
    min_amount_cents: z
      .int()
      .openapi({
        description:
          'The minimum spending amount required for the charge, measured in cents and excluding any applicable taxes. It indicates the minimum amount that needs to be charged for each billing period.',
        example: 1200,
      }),
    properties: ChargeObjectPropertiesSchema.openapi({
      description: 'List of all thresholds utilized for calculating the charge.',
    }),
    filters: z
      .array(ChargeFilterObjectSchema)
      .openapi({
        description:
          'List of filters used to apply differentiated pricing based on additional event properties.',
      }),
    taxes: z
      .array(TaxObjectSchema)
      .exactOptional()
      .openapi({ description: 'All taxes applied to the charge.' }),
    applied_pricing_unit: z
      .object({
        code: z
          .string()
          .openapi({ description: 'The code of the pricing unit.', example: 'unit_code' }),
        conversion_rate: z
          .string()
          .openapi({
            description: "The conversion rate from pricing units to the plan's currency.",
            example: '0.5',
          }),
      })
      .nullable()
      .exactOptional()
      .openapi({
        required: ['code', 'conversion_rate'],
        description: 'The pricing unit applied to the charge.',
      }),
    accepts_target_wallet: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Specifies whether the charge accepts a target wallet for prepaid credits deduction.\nWhen `true`, events may include a `target_wallet_code` in their `properties` to direct credit deduction to a specific wallet.\nThis field requires a premium integration.',
        example: false,
      }),
    lago_parent_id: z
      .uuid()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Unique identifier of the parent charge (if this is an override).',
        example: '1a901a90-1a90-1a90-1a90-1a901a901a90',
      }),
  })
  .openapi({
    required: [
      'lago_id',
      'lago_billable_metric_id',
      'billable_metric_code',
      'created_at',
      'charge_model',
      'invoiceable',
      'regroup_paid_fees',
      'pay_in_advance',
      'prorated',
      'min_amount_cents',
      'properties',
      'filters',
    ],
  })
  .openapi('ChargeObject')

