const PageParamsSchema = z
  .preprocess(
    (val) =>
      typeof val === 'string' &&
      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
        ? Number(val)
        : val,
    z.int(),
  )
  .exactOptional()
  .openapi({
    param: {
      name: 'page',
      in: 'query',
      description:
        'Page number. Defaults to 1. A value that is not a positive integer, such as `0`, returns the first page.',
      required: false,
      explode: true,
      schema: { type: 'integer', example: 1 },
    },
    example: 1,
  })

