export const getCustomersExternalCustomerIdPastUsageRoute = createRoute({
  method: 'get',
  path: '/customers/{external_customer_id}/past_usage',
  tags: ['customers'],
  summary: 'Retrieve customer past usage',
  description:
    'This endpoint enables the retrieval of the usage-based billing data for a customer within past periods.',
  operationId: 'findAllCustomerPastUsage',
  request: {
    query: z.object({
      page: PageParamsSchema,
      per_page: PerPageParamsSchema,
      external_subscription_id: z
        .string()
        .openapi({
          param: {
            name: 'external_subscription_id',
            in: 'query',
            description: 'The unique identifier of the subscription within your application.',
            required: true,
            explode: true,
            schema: { type: 'string', example: 'sub_1234567890' },
          },
          example: 'sub_1234567890',
        }),
      billable_metric_code: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'billable_metric_code',
            in: 'query',
            description: 'Billable metric code filter to apply to the charge usage',
            required: false,
            explode: true,
            schema: { type: 'string', example: 'cpu' },
          },
          example: 'cpu',
        }),
      periods_count: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'periods_count',
            in: 'query',
            description: 'Number of past billing period to returns in the result',
            required: false,
            explode: true,
            schema: { type: 'integer', example: 5 },
          },
          example: 5,
        }),
    }),
    params: z.object({
      external_customer_id: z
        .string()
        .openapi({
          param: {
            name: 'external_customer_id',
            in: 'path',
            description:
              'The customer external unique identifier (provided by your own application).',
            required: true,
            schema: { type: 'string', example: '5eb02857-a71e-4ea2-bcf9-57d3a41bc6ba' },
          },
          example: '5eb02857-a71e-4ea2-bcf9-57d3a41bc6ba',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Customer past usage',
      content: { 'application/json': { schema: CustomerPastUsageSchema } },
    },
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
  },
})

