export const postOrderFormsLagoIdMarkAsSignedRoute = createRoute({
  method: 'post',
  path: '/order_forms/{lago_id}/mark_as_signed',
  tags: ['order_forms'],
  summary: 'Mark an order form as signed',
  description:
    "This endpoint records the customer's signature on an order form, and creates the order that carries the quoted deal out.\nOnly a `generated` order form can be signed, so a `422` is returned once the order form has been signed, has expired or has been voided.\nAn `execute_at` landing on or after the day the quoted deal stops being executable is rejected as well, so the order can never be scheduled past the term it bills.\nA concurrent write on the same quote is reported as a `422` rather than retried, so a duplicated call can fail while the first one is still in flight.\nThis is a premium feature.",
  operationId: 'markOrderFormAsSigned',
  request: {
    params: z.object({ lago_id: LagoOrderFormIdParamsSchema }),
    body: {
      description: 'Mark order form as signed payload',
      content: { 'application/json': { schema: OrderFormMarkAsSignedInputSchema } },
    },
  },
  responses: {
    200: {
      description: 'Order form marked as signed',
      content: { 'application/json': { schema: OrderFormSchema } },
    },
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
  },
})

