export const postQuoteVersionsLagoIdApproveRoute = createRoute({
  method: 'post',
  path: '/quote_versions/{lago_id}/approve',
  tags: ['quotes'],
  summary: 'Approve a quote version',
  description:
    "This endpoint approves a quote version and generates the order form to send to the customer for signature.\nOnly a `draft` version can be approved, and its `billing_items` must be complete: approval validates them against the catalog and against the customer, and returns a `422` when the deal cannot be executed as quoted.\nThe `expires_at` of the generated order form is bounded by the deal's own term, so a signing window reaching beyond the day the deal stops being executable is rejected.\nA concurrent write on the same quote is reported as a `422` rather than retried, so a duplicated call can fail while the first one is still in flight.\nThis is a premium feature.",
  operationId: 'approveQuoteVersion',
  request: {
    params: z.object({ lago_id: LagoQuoteVersionIdParamsSchema }),
    body: {
      description: 'Approve quote version payload',
      content: { 'application/json': { schema: QuoteVersionApproveInputSchema } },
    },
  },
  responses: {
    200: {
      description: 'Quote version approved',
      content: { 'application/json': { schema: QuoteVersionSchema } },
    },
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
  },
})

