export const deleteSubscriptionsExternalIdRoute = createRoute({
  method: 'delete',
  path: '/subscriptions/{external_id}',
  tags: ['subscriptions'],
  summary: 'Terminate a subscription',
  description: 'This endpoint allows you to terminate a subscription.',
  operationId: 'destroySubscription',
  request: {
    params: z.object({
      external_id: z
        .string()
        .openapi({
          param: {
            name: 'external_id',
            in: 'path',
            description: 'External ID of the existing subscription',
            required: true,
            schema: { type: 'string', example: '5eb02857-a71e-4ea2-bcf9-57d3a41bc6ba' },
          },
          example: '5eb02857-a71e-4ea2-bcf9-57d3a41bc6ba',
        }),
    }),
    query: z.object({
      status: z
        .string()
        .default('active')
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            description:
              'Selects which subscription to terminate for the given `external_id`, based on its status. If the field is not defined, Lago targets only `active` subscriptions.\n\n- `pending`: cancel a subscription scheduled for a future activation (include `status=pending`).\n- `incomplete`: cancel a payment-gated subscription that is still awaiting its activation payment (include `status=incomplete`). The subscription is canceled with `cancellation_reason: manual`, its invoice is closed and nothing is billed, and any pending payment is canceled on a best-effort basis with the payment provider (some provider statuses cannot be canceled). Applied coupons, credit notes and wallet credits are recredited. Termination behaviours (`on_termination_credit_note`, `on_termination_invoice`) are ignored, as an incomplete subscription has never been billed.\n',
            required: false,
            explode: true,
            schema: { type: 'string', example: 'incomplete', default: 'active' },
          },
          example: 'incomplete',
        }),
      on_termination_credit_note: z
        .enum(['credit', 'refund', 'offset', 'skip'])
        .exactOptional()
        .openapi({
          param: {
            name: 'on_termination_credit_note',
            in: 'query',
            description:
              'When a pay-in-advance subscription is terminated before the end of its billing period, we generate a credit note for the unused subscription time by default.\nThis field allows you to control the behavior of the credit note generation:\n\n- `credit`: A credit note is generated for the unused subscription time. The unused amount is credited back to the customer.\n- `refund`: A credit note is generated for the unused subscription time. If the invoice is paid or partially paid, the unused paid amount is refunded; any unpaid unused amount is credited back to the customer.\n- `offset`: A credit note is generated for the unused subscription time. If the invoice is paid or partially paid, the unused paid amount is refunded; any unpaid unused amount is applied to the invoice reducing its amount due.\n- `skip`: No credit note is generated for the unused subscription time.\n\n_Note: This field is only applicable to pay-in-advance plans and is ignored for pay-in-arrears plans._\n',
            required: false,
            schema: {
              type: 'string',
              enum: ['credit', 'refund', 'offset', 'skip'],
              example: 'credit',
            },
          },
          example: 'credit',
        }),
      on_termination_invoice: z
        .enum(['generate', 'skip'])
        .exactOptional()
        .openapi({
          param: {
            name: 'on_termination_invoice',
            in: 'query',
            description:
              'When a subscription is terminated before the end of its billing period, we generate an invoice for the unbilled usage.\nThis field allows you to control the behavior of the invoice generation:\n\n- `generate`: An invoice is generated for the unbilled usage.\n- `skip`: No invoice is generated for the unbilled usage.\n',
            required: false,
            schema: { type: 'string', enum: ['generate', 'skip'], example: 'generate' },
          },
          example: 'generate',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Subscription terminated',
      content: { 'application/json': { schema: SubscriptionExtendedSchema } },
    },
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    405: NotAllowedResponse,
    422: UnprocessableEntityResponse,
  },
})

